package br.com.athletix.tarefa.controller;
import br.com.athletix.evento.service.OrganizacaoEventoAuthorizationService; import br.com.athletix.security.AutorizacaoAtualService; import br.com.athletix.tarefa.dto.*; import br.com.athletix.tarefa.service.TarefaService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/tarefas") public class TarefaController {final TarefaService s;final AutorizacaoAtualService a;final OrganizacaoEventoAuthorizationService o;public TarefaController(TarefaService s,AutorizacaoAtualService a,OrganizacaoEventoAuthorizationService o){this.s=s;this.a=a;this.o=o;}@PostMapping public ResponseEntity<TarefaResponse> criar(@Valid @RequestBody TarefaRequests.Create q,Authentication au,HttpServletRequest r){o.exigirOrganizadorOuAdministrador(q.eventoId(),au,r);return ResponseEntity.status(201).body(TarefaResponse.from(s.criar(q,a.membroAtual(au,r))));}@GetMapping("/{id}") public TarefaResponse get(@PathVariable Long id){return TarefaResponse.from(s.buscar(id));}@PutMapping("/{id}") public TarefaResponse put(@PathVariable Long id,@Valid @RequestBody TarefaRequests.Update q,Authentication au,HttpServletRequest r){o.exigirOrganizadorOuAdministrador(s.buscar(id).getEventoId(),au,r);return TarefaResponse.from(s.alterar(id,q));}@PatchMapping("/{id}/status") public TarefaResponse status(@PathVariable Long id,@Valid @RequestBody TarefaRequests.Status q,Authentication au,HttpServletRequest r){var t=s.buscar(id);o.exigirOrganizadorOuAdministrador(t.getEventoId(),au,r);return TarefaResponse.from(s.status(id,q));}}
